# data-s14.json do fetch_build_s14.py sinh. build_s14.py KHÔNG chứa data.
# Usage: python3 build_s14.py ../data-s14.json
import json, re, sys
from sprints import nav_html
DATA = json.load(open(sys.argv[1] if len(sys.argv)>1 else "data-s14.json"))
NAV = nav_html("Sprint 14")   # menu điều hướng sprint (sprint hiện tại = active)

# CSS lấy từ _head.html (chỉ block <style>)
css = re.search(r'<style>.*?</style>', open("_head.html").read(), re.S).group(0)

