PIC_ORDER = ["Khoa", "Đạt", "Biên", "Minh", "Hưng"]
ST = {"done": ("pill-approved", "✅ migrated"),
      "wip":  ("pill-changes",  "🟡 WIP"),
      "todo": ("pill-todo",     "🔴 chưa")}

def _esc(s):
    return str(s).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")

def screens_section():
    done = sum(1 for s in SCREENS if s[5] == "done")
    wip  = sum(1 for s in SCREENS if s[5] == "wip")
    todo = sum(1 for s in SCREENS if s[5] == "todo")
    # tóm tắt theo PIC: migrated / tổng
    chips = []
    for pic in PIC_ORDER:
        rows = [s for s in SCREENS if s[4] == pic]
        d = sum(1 for s in rows if s[5] == "done")
        full = " full" if d == len(rows) else ""
        b = ' style="color:var(--accent)"' if pic == "Biên" else ""
        chips.append('<div class="pic-chip"><b'+b+'>'+_esc(pic)+'</b>'
                     '<span class="frac'+full+'">'+str(d)+'/'+str(len(rows))+'</span></div>')
    # các dòng bảng
    body = []
    for sid, name, route, tk, pic, st, note in SCREENS:
        cls, lbl = ST[st]
        rt = '<span class="ticket">'+_esc(route)+'</span>' if route else '<span class="cf-na">—</span>'
        picc = ' style="color:var(--accent);font-weight:600"' if pic == "Biên" else ""
        body.append('<tr>'
            '<td><span class="ticket">'+str(sid)+'</span></td>'
            '<td><span class="jp-cell">'+_esc(name)+'</span></td>'
            '<td>'+rt+'</td>'
            '<td><span class="ticket">'+_esc(tk)+'</span></td>'
            '<td><span class="dev"'+picc+'>'+_esc(pic)+'</span></td>'
            '<td><span class="pill '+cls+'">'+lbl+'</span></td>'
            '<td><span class="note-cell">'+_esc(note)+'</span></td>'
            '</tr>')
    return ('<div class="page">'
        '<div class="page-header"><h1>画面一覧 — Sprint 14 (在庫 / Inventory)</h1>'
        '<span class="meta">'+str(len(SCREENS))+' màn · snapshot code '+SNAP+' (thủ công, không auto-update)</span></div>'
        '<div class="subtitle">Tiến độ migrate + người phụ trách (PIC) từng màn, đọc từ repo nhánh '
        '<b>mimosa/frontend/develop/r20260727</b>. Trạng thái theo <b>code thật</b>, không theo status field Backlog. '
        '<a href="#" onclick="scrollTo(0,0);return false" style="font-family:inherit;font-size:12px">↑ Table A (PR tracking) phía trên</a></div>'
        '<div class="stats">'
          '<div class="stat"><span class="stat-val">'+str(len(SCREENS))+'</span> màn</div>'
          '<div class="stat">✅ migrated <span class="stat-val" style="color:var(--report-fg)">'+str(done)+'</span></div>'
          '<div class="stat">🟡 WIP <span class="stat-val warn">'+str(wip)+'</span></div>'
          '<div class="stat">🔴 chưa <span class="stat-val warn">'+str(todo)+'</span></div>'
        '</div>'
        '<div class="pic-summary">'+''.join(chips)+'</div>'
        '<div class="scroll-wrap"><table style="min-width:900px">'
        '<thead><tr>'
          '<th>Screen ID</th><th>画面名</th><th>Route Next.js</th><th>Ticket</th>'
          '<th>PIC</th><th>状態</th><th>Ghi chú</th>'
        '</tr></thead><tbody>'+''.join(body)+'</tbody></table></div>'
        '<div class="footnote">'
          'PIC = người phụ trách (Backlog). ✅ migrated = đã merge vào r20260727 · '
          '🟡 WIP = đã có branch/code nhưng chưa merge vào r · 🔴 chưa = chưa có code. '
          'Route dạng <code>stocks/xxx/</code> (không có <code>/</code> đầu) = folder trên feature branch, chưa lên r.<br>'
          '⚠️ Bảng này là ảnh chụp thủ công ngày '+SNAP+' — không tự làm mới như bảng PR bên dưới.</div>'
        '</div>')

SCREENS_HTML = screens_section()

RENDER_JS = r"""
function esc(s){return String(s).replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));}
function render(D){
  var U=D.prUrlBase, COMMON=new Set(D.common), INVALID=new Set(D.invalidBase);
  var PILL={merged:['merged','MERGED'],draft:['draft','DRAFT'],approved:['approved','APPROVED'],changes:['changes','CHANGES'],open:['open','OPEN']};
  function pill(st){var x=PILL[st]||PILL.open;return '<span class="pill pill-'+x[0]+'">'+x[1]+'</span>';}
  function one(p,inv){
    var mark=p.cf==='bad'?'<span class="cf-bad">✗</span>':(p.cf==='unk'?'<span class="cf-unk" title="GitHub chưa tính xong mergeable">?</span>':'<span class="cf-ok">✓</span>');
    var inb=inv?' <span class="badge-invalid" title="ルール違反">invalid</span>':'';
    var nc=(p.nc!=null)?' <span class="commits" title="số commit trong PR (branch vượt base)">'+p.nc+'c</span>':'';
    var fcv=(p.fc!=null)?' <span class="files" title="số file thay đổi">'+p.fc+'f</span>':'';
    var df=(p.add!=null||p.del!=null)?' <span class="adds" title="số dòng thêm">+'+(p.add||0)+'</span><span class="dels" title="số dòng xoá">−'+(p.del||0)+'</span>':'';
    return '<a href="'+U+p.num+'" target="_blank" rel="noopener">#'+p.num+'</a>'+inb+' '+pill(p.st)+' '+mark+nc+fcv+df;
  }
  function cell(prs,inv){
    if(!prs||!prs.length) return '<span class="cf-na">—</span>';
    return prs.map(function(p){return one(p,inv);}).join('<br>');
  }
  function unb(n){return n>0?'<span class="unresolved">'+n+'</span>':'0';}
  function cnt(a){return a?a.length:0;}
  // reviewers: ✓approve (xanh) · ✗changes (đỏ) · ⏳được request chưa review (xám)
  function rvwCell(r){
    if(!r) return '<span class="cf-na">—</span>';
    var o=[];
    (r.ap||[]).forEach(function(n){o.push('<span class="rv-ap" title="đã approve">✓'+esc(n)+'</span>');});
    (r.ch||[]).forEach(function(n){o.push('<span class="rv-ch" title="request changes">✗'+esc(n)+'</span>');});
    (r.pd||[]).forEach(function(n){o.push('<span class="rv-pd" title="được assign, chưa review">⏳'+esc(n)+'</span>');});
    return o.length?o.join(' '):'<span class="cf-na">—</span>';
  }

  // ---- helper: 1 row bảng chính ----
  function mainRow(r){
    var devcls=(r.dev==='bien')?'dev dev-bien':'dev';
    var rep=r.drive?'<span class="report-yes">✓</span>':'<span class="report-no">—</span>';
    return '<tr>'
      +'<td><span class="ticket">'+r.ticket+'</span></td>'
      +'<td><span class="'+devcls+'">'+r.dev+'</span></td>'
      +'<td>'+cell(r.base||[],INVALID.has(r.ticket))+'</td>'
      +'<td>'+cell(r.r727||[],false)+'</td>'
      +'<td><span class="date-cell">'+r.created+'</span></td>'
      +'<td class="rvw-cell">'+rvwCell(r.rvw)+'</td>'
      +'<td>'+rep+'</td>'
      +'<td><span class="copilot-cell">'+r.cop+'</span></td>'
      +'<td>'+unb(r.unres)+'</td>'
      +'<td><span class="title-cell">'+esc(r.title)+'</span></td>'
    +'</tr>';
  }
  // ---- helper: 1 block bảng chính (heading + stats + table) ----
  function mainBlock(rows,title,sub){
    var nbase=0,nr727=0,npr=0,totun=0,ncf=0;
    var body=rows.map(function(r){
      var b=r.base||[],r727=r.r727||[];
      nbase+=cnt(b);nr727+=cnt(r727);npr+=cnt(b)+cnt(r727);totun+=r.unres;
      [b,r727].forEach(function(a){a.forEach(function(p){if(p.cf==='bad')ncf++;});});
      return mainRow(r);
    }).join('');
    return '<h2 style="font-size:15px;font-weight:700;margin:24px 0 4px;letter-spacing:-0.01em;">'+title+'</h2>'
      +'<div class="subtitle">'+sub+'</div>'
      +'<div class="stats">'
        +'<div class="stat"><span class="stat-val">'+rows.length+'</span> ticket</div>'
        +'<div class="stat"><span class="stat-val">'+npr+'</span> PR</div>'
        +'<div class="stat">→base <span class="stat-val">'+nbase+'</span></div>'
        +'<div class="stat">→r727 <span class="stat-val">'+nr727+'</span></div>'
        +'<div class="stat">conflict <span class="stat-val warn">'+ncf+'</span></div>'
        +'<div class="stat">Copilot unres <span class="stat-val warn">'+totun+'</span></div>'
      +'</div>'
      +'<div class="scroll-wrap"><table><thead><tr>'
        +'<th>Ticket</th><th>Dev</th><th>→base</th><th>→r20260727</th>'
        +'<th>Created</th><th>Reviewers</th><th>Report</th><th>Copilot</th><th>Unres.</th><th>Title</th>'
      +'</tr></thead><tbody>'+body+'</tbody></table></div>';
  }
  var commonRows=D.main.filter(function(r){return COMMON.has(r.ticket);});
  var normalRows=D.main.filter(function(r){return !COMMON.has(r.ticket);});

  // ---- bảng phụ scaffold ----
  var scfUn=0,scfCf=0;
  var scfRows=D.scaffold.map(function(r){
    scfUn+=r.unres; if(r.pr.cf==='bad')scfCf++;
    var devcls=(r.dev==='bien')?'dev dev-bien':'dev';
    return '<tr>'
      +'<td><span class="ticket">'+r.ticket+'</span></td>'
      +'<td><span class="'+devcls+'">'+r.dev+'</span></td>'
      +'<td>'+cell([r.pr],false)+'</td>'
      +'<td><span class="date-cell">'+r.created+'</span></td>'
      +'<td class="rvw-cell">'+rvwCell(r.rvw)+'</td>'
      +'<td><span class="copilot-cell">'+r.cop+'</span></td>'
      +'<td>'+unb(r.unres)+'</td>'
      +'<td><span class="title-cell">'+esc(r.title)+'</span></td>'
    +'</tr>';
  }).join('');

  var html='<div class="page">'
   +'<div class="page-header"><h1>Table A — Sprint 14</h1>'
     +'<span class="meta">cập nhật '+D.updated+' · repo '+D.repo+'</span></div>'
   +'<div class="subtitle">PR team-dev Rikkei tạo từ <b>2026-07-27</b> vào <b>develop/base</b> / <b>r20260727</b> — chia 2 bảng: common component vs màn/fix thường. Loại PR CLOSED và sync/chore/evidence. <a href="index.html" style="font-family:inherit;font-size:12px">← Sprint 13</a></div>'
   + mainBlock(commonRows,'Bảng 1 — Common component (共通)','Ticket nhánh <b>common-…</b>. Copilot chỉ đếm PR→base.')
   + mainBlock(normalRows,'Bảng 2 — Màn / Fix thường','Ticket nhánh ANGULAR_REPLACE-… (màn migration + fix lẻ).')
   +'<h2 style="font-size:15px;font-weight:700;margin:26px 0 4px;letter-spacing:-0.01em;">Bảng phụ — PR → '+D.scaffoldBranch.split('/').pop()+' <span style="font-weight:400;color:var(--text-dim);font-size:12px;">(giàn giáo / bake rule vào SKILL)</span></h2>'
   +'<div class="subtitle">PR trỏ vào nhánh <b>'+D.scaffoldBranch.split('/').pop()+'</b> — cập nhật giàn giáo (rules + frontend-screen-* SKILL). Loại PR sync base/r727→scaffold.</div>'
   +'<div class="stats">'
     +'<div class="stat"><span class="stat-val">'+D.scaffold.length+'</span> PR sống</div>'
     +'<div class="stat">conflict <span class="stat-val warn">'+scfCf+'</span></div>'
     +'<div class="stat">Copilot unresolved <span class="stat-val warn">'+scfUn+'</span></div>'
   +'</div>'
   +'<div class="scroll-wrap"><table style="min-width:1000px;"><thead><tr>'
     +'<th>Ticket</th><th>Dev</th><th>→scaffold</th><th>Created</th><th>Reviewers</th><th>Copilot</th><th>Unres.</th><th>Title</th>'
   +'</tr></thead><tbody>'+scfRows+'</tbody></table></div>'
   +'<div class="footnote">Status pill theo từng PR: '
     +'<span class="pill pill-open">OPEN</span> <span class="pill pill-draft">DRAFT</span> '
     +'<span class="pill pill-approved">APPROVED</span> <span class="pill pill-changes">CHANGES</span> '
     +'<span class="pill pill-merged">MERGED</span>.<br>'
     +'Conflict: ✓ MERGEABLE / ✗ CONFLICTING. Report ✓ = có link Drive self-review.<br>'
     +'Reviewers (theo PR→base): <span class="rv-ap">✓tên</span> đã approve · <span class="rv-ch">✗tên</span> request changes · <span class="rv-pd">⏳tên</span> được assign chưa review.<br>'
     +'🔴 Bảng 1 (common) đếm Copilot chỉ từ PR→base (bỏ r727 cùng code sync).<br>'
     +'Created = thời điểm tạo PR sớm nhất của ticket, định dạng MM-DD HH:MM (giờ VN, UTC+7).</div>'
   +'</div>';
  document.getElementById('app').innerHTML=html;
  // linh vật: bubble báo số PR đang conflict
  var bad=0;
  D.main.forEach(function(r){['base','r629','r713','r727'].forEach(function(k){
    (r[k]||[]).forEach(function(p){if(p.cf==='bad')bad++;});});});
  (D.scaffold||[]).forEach(function(r){if(r.pr&&r.pr.cf==='bad')bad++;});
  // báo tình hình conflict cho con đầu đàn (thư viện pixel-pets nạp bằng defer nên có thể chậm hơn)
  var msg = bad ? ('\u26a0\ufe0f '+bad+' PR \u0111ang conflict') : '\u2705 Kh\u00f4ng PR n\u00e0o conflict';
  (function tell(n){
    if(window.PixelPets && window.PixelPets.pets && window.PixelPets.pets.length) window.PixelPets.say(msg);
    else if(n>0) setTimeout(function(){tell(n-1);}, 600);
  })(8);
}
function fetchData(){
  // Data ở nhánh `data` (KHÔNG phải nguồn Pages) → fetch qua raw.githubusercontent (CORS *, cache ~5p).
  // Cron push data vào nhánh data → KHÔNG trigger Pages build → không bao giờ chạm rate-limit.
  var DATA_URL='https://raw.githubusercontent.com/nguyenducbien-art/w3-pr-tracking-tables/data/data-s14.json';
  return fetch(DATA_URL+'?t='+Date.now()).then(function(r){return r.json();}).then(render)
    .catch(function(e){var a=document.getElementById('app'); if(!a.innerHTML) a.innerHTML='<p style="color:red;padding:20px">Fetch data error: '+e+'</p>';});
}
(function(){
  var el=document.getElementById('table-data');
  var txt=el?el.textContent.trim():'';
  if(txt){ try{render(JSON.parse(txt));}catch(e){document.getElementById('app').innerHTML='<p style="color:red;padding:20px">JSON error: '+e+'</p>';} return; }
  fetchData();
  setInterval(fetchData, 60000);  // tab mở tự re-fetch mỗi 1 phút (cache-buster ?t= → raw tươi ~3s)
})();
document.addEventListener('click',function(e){
  var a=e.target.closest&&e.target.closest('a[href^="http"]');
  if(a){e.preventDefault();window.open(a.href,'_blank','noopener');}
},true);

"""

TITLE = "Table A — Sprint 14"
FAVICON = "<link rel=\"icon\" href=\"data:image/x-icon;base64,\">"  # mimosa stg favicon

def build(inline):
    if inline:
        data_script = '<script id="table-data" type="application/json">'+json.dumps(DATA,ensure_ascii=False)+'</script>'
    else:
        data_script = '<script id="table-data" type="application/json"></script>'
    inner = ('<title>'+TITLE+'</title>\n'+FAVICON+'\n'+css+'\n'
             +NAV+'\n<div id="app"></div>\n'+SCREENS_HTML+'\n'+MASCOT+'\n'+data_script+'\n<script>'+RENDER_JS+'</script>')
    return inner

# artifact = fragment + inline JSON
open("table-a-s14.html","w").write(build(True))

# hosted = full document, fetch data-s14.json
doc = ('<!DOCTYPE html>\n<html lang="vi">\n<head>\n<meta charset="utf-8">\n'
       '<meta name="viewport" content="width=device-width, initial-scale=1">\n'
       '<meta name="robots" content="noindex, nofollow">\n<title>'+TITLE+'</title>\n'+FAVICON+'\n'+css+'\n</head>\n<body>\n'
       +NAV+'\n<div id="app"></div>\n'+SCREENS_HTML+'\n'+MASCOT+'\n<script id="table-data" type="application/json"></script>\n<script>'+RENDER_JS+'</script>\n</body>\n</html>')
open("s14.html","w").write(doc)

print("built shell: s14.html (fetch) + table-a-s14.html (artifact,inline) từ data-s14.json |",
      len(DATA["main"]),"main +",len(DATA["scaffold"]),"scaffold")
